\begin{ex}%[6H5N2]
\immini[thm]{
Tìm trục đối xứng và tâm đối xứng của hình ảnh sau
}{
\begin{tikzpicture}[scale =0.5]

    % Vẽ nền tròn đối xứng
    \draw[blue, thick] (0,0) circle (5);

    % Vẽ các đường xoắn ốc
    \foreach \angle in {0, 45, 90, 135, 180, 225, 270, 315} {
        \draw[red, thick, domain=0:4, samples=100] plot ({\x*cos(\angle) - \x*sin(\angle)}, {\x*sin(\angle) + \x*cos(\angle)});
    }

    % Vẽ các ngôi sao đối xứng qua tâm
    \foreach \a in {0, 90, 180, 270} {
        \draw[fill=yellow, rotate=\a] (3,0) -- (3.5,0.5) -- (4,0) -- (3.5,-0.5) -- cycle;
    }

    % Vẽ các đường thẳng chia hình tròn thành các phần đối xứng
    \foreach \ang in {0, 30, 60, 90, 120, 150, 180, 210, 240, 270, 300, 330} {
        \draw[green, thick] (0,0) -- ({5*cos(\ang)}, {5*sin(\ang)});
    }

    % Thêm các vòng tròn nhỏ đối xứng qua tâm
    \foreach \radius in {1, 2, 3, 4} {
        \draw[dashed, purple] (0,0) circle (\radius);
    }

\end{tikzpicture}
}
